def get_delegated_vars_and_hostname(self, templar, task, variables):
    """Return delegated host variables and the final delegate_to hostname."""
    if task.delegate_to is None:
        return {}, None

    delegated_host_name = templar.template(task.delegate_to, fail_on_undefined=False)
    if delegated_host_name is None:
        raise AnsibleError(message="Undefined delegate_to host for task:", obj=task._ds)
    if not isinstance(delegated_host_name, string_types):
        raise AnsibleError(message="the field 'delegate_to' has an invalid type (%s), and could not be"
                           " converted to a string type." % type(delegated_host_name), obj=task._ds)

    delegated_host_vars = {}

        # now try to find the delegated-to host in inventory, or failing that,
        # create a new host on the fly so we can fetch variables for it
        delegated_host = None
        if self._inventory is not None:
            delegated_host = self._inventory.get_host(delegated_host_name)
            # try looking it up based on the address field, and finally
            # fall back to creating a host on the fly to use for the var lookup
            if delegated_host is None:
                for h in self._inventory.get_hosts(ignore_limits=True, ignore_restrictions=True):
                    # check if the address matches, or if both the delegated_to host
                    # and the current host are in the list of localhost aliases
                    if h.address == delegated_host_name:
                        delegated_host = h
                        break
                else:
                    delegated_host = Host(name=delegated_host_name)
        else:
            delegated_host = Host(name=delegated_host_name)

        # now we go fetch the vars for the delegated-to host and save them in our
        # master dictionary of variables to be used later in the TaskExecutor/PlayContext
        delegated_host_vars[delegated_host_name] = self.get_vars(
            play=task.get_play(),
            host=delegated_host,
            task=task,
            include_delegate_to=False,
            include_hostvars=True,
        )
        delegated_host_vars[delegated_host_name]['inventory_hostname'] = variables.get('inventory_hostname')

    return delegated_host_vars, delegated_host_name

def _get_delegated_vars(self, play, task, existing_variables):
    """Deprecated: use get_delegated_vars_and_hostname instead."""
    if not hasattr(task, 'loop'):
        return {}, None
    templar = Templar(loader=self._loader, variables=existing_variables)
    delegated_vars, _ = self.get_delegated_vars_and_hostname(templar, task, existing_variables)
    return delegated_vars, None

